const item=$input.first().json;
const body=item.body||item;
function norm(p){if(!p)return'';const s=String(p).trim();if(s.startsWith('+'))return'+'+s.replace(/\D/g,'');const d=s.replace(/\D/g,'');if(d.length===9)return'+34'+d;if(d.length>=10)return'+'+d;return'+34'+d;}
const phone=norm(body.telephone||body.phone||body.phone_number);
if(!phone) throw new Error('telephone requis');
const provider=($env.TELEPHONY_PROVIDER||'twilio').toLowerCase();
const campaign=body.campaign||$env.CAMPAIGN_ID||'sofia-test-maroc-juin2026';
return [{json:{telephone:phone,lead_id:body.lead_id||'',nombre:body.nombre||body.first_name||'Sofía',provider,campaign}}];

const row=$('Prepare + Provider').first().json;
const sid=$env.TWILIO_ACCOUNT_SID;
const token=$env.TWILIO_AUTH_TOKEN;
const from=$env.TWILIO_PHONE_NUMBER;
const base=($env.N8N_WEBHOOK_URL||'').replace(/\/$/, '');
const auth=Buffer.from(sid+':'+token).toString('base64');
const res=await this.helpers.httpRequest({method:'POST',url:`https://api.twilio.com/2010-04-01/Accounts/${sid}/Calls.json`,headers:{Authorization:'Basic '+auth,'Content-Type':'application/x-www-form-urlencoded'},body:{To:row.telephone,From:from,Url:base+'/telephony/twilio/start',Record:'true',RecordingStatusCallback:base+'/telephony/twilio/recording',MachineDetection:'DetectMessageEnd',AsyncAmdStatusCallback:base+'/telephony/twilio/amd',Timeout:'30'},json:false});
return [{json:{...row,provider:'twilio',call_raw:res}}];

const row=$('Prepare + Provider').first().json;
const base=($env.N8N_WEBHOOK_URL||'').replace(/\/$/, '');
const res=await this.helpers.httpRequest({method:'POST',url:'https://api.telnyx.com/v2/calls',headers:{Authorization:'Bearer '+$env.TELNYX_API_KEY,'Content-Type':'application/json'},body:{to:row.telephone,from:$env.TELNYX_PHONE_NUMBER,connection_id:$env.TELNYX_CONNECTION_ID,webhook_url:base+'/telephony/telnyx/start',record_audio:true,record_format:'mp3',answering_machine_detection:'premium'},json:true});
return [{json:{...row,provider:'telnyx',call_raw:res}}];

const row=$('Prepare + Provider').first().json;
const url=$env.VICIDIAL_API_URL+'?source=doorway_odoo&user='+encodeURIComponent($env.VICIDIAL_USER)+'&pass='+encodeURIComponent($env.VICIDIAL_PASS)+'&function=call_out_number&campaign='+encodeURIComponent(row.campaign)+'&phone_number='+encodeURIComponent(row.telephone.replace('+',''))+'&phone_code=34&outbound_cid='+encodeURIComponent($env.SIP_PHONE_NUMBER||$env.TWILIO_PHONE_NUMBER||'');
const text=await this.helpers.httpRequest({method:'GET',url,json:false});
return [{json:{...row,provider:'vicidial',call_raw:text,ok:!String(text).includes('ERROR')}}];
